    <div class="content">
        <h1 id="introduction">Introduction</h1>
<p>REST API for Snackzar — Bihar's premium Makhana &amp; snacks ecommerce marketplace. Supports User, Seller, Delivery Partner, and Admin panels.</p>
<aside>
    <strong>Base URL</strong>: <code>http://localhost</code>
</aside>
<h2 id="welcome-to-the-snackzar-api">Welcome to the Snackzar API</h2>
<p>This API powers the Snackzar ecommerce platform — a multi-vendor marketplace for Bihar's finest snacks.</p>
<h3 id="authentication">Authentication</h3>
<p>All protected endpoints require a <strong>Bearer token</strong> obtained via the Login endpoint. Include the token in the <code>Authorization</code> header:</p>
<pre><code>Authorization: Bearer {YOUR_AUTH_TOKEN}</code></pre>
<h3 id="roles">Roles</h3>
<ul>
<li><strong>User</strong>: Browse products, manage cart, place orders</li>
<li><strong>Seller</strong>: Manage products, fulfill orders, view payouts</li>
<li><strong>Delivery Partner</strong>: Accept/manage delivery assignments</li>
<li><strong>Admin</strong>: Full platform management</li>
</ul>
<h3 id="response-format">Response Format</h3>
<p>All API responses follow a consistent format:</p>
<pre><code class="language-json">{
  "success": true,
  "message": "Success",
  "data": { ... }
}</code></pre>
<aside>Code examples are shown on the right (or below on mobile). Switch languages using the tabs.</aside>

        <h1 id="authenticating-requests">Authenticating requests</h1>
<p>To authenticate requests, include an <strong><code>Authorization</code></strong> header with the value <strong><code>"Bearer {YOUR_AUTH_KEY}"</code></strong>.</p>
<p>All authenticated endpoints are marked with a <code>requires authentication</code> badge in the documentation below.</p>
<p>Obtain a token by calling the <b>POST /api/v1/login</b> endpoint with your email and password. The token is returned in the response body.</p>

        <h1 id="addresses">Addresses</h1>

    <p>APIs for managing user delivery addresses (CRUD, set default).</p>

                                <h2 id="addresses-GETapi-v1-user-addresses">GET api/v1/user/addresses</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-GETapi-v1-user-addresses">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/v1/user/addresses" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/v1/user/addresses"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
    method: "GET",
    headers,
}).then(response =&gt; response.json());</code></pre></div>

</span>

